	[[nodiscard]] inline bool HasCounterVariant(const ShaderProgramRef& program) noexcept
	{
		if (program.m_Stage != ShaderStage::Pixel && program.m_Stage != ShaderStage::Compute)
		{
			return false;
		}
		for (const auto id : Programs)
		{
			if (program.m_ProgramId == id)
			{
				return true;
			}
		}
		return false;
	}
	[[nodiscard]] inline ShaderProgramRef CounterVariant(ShaderProgramRef program)
	{
		if (HasCounterVariant(program) && !program.m_VariantId.ends_with(VariantSuffix))
		{
			program.m_VariantId += VariantSuffix;
		}
		return program;
	}
